  display: grid; grid-template-columns: max-content 1fr; gap: .2rem .8rem;
  font-size: .9rem; padding: .6rem .8rem; border-radius: 6px; background: var(--code-bg);
}
.compare dt { color: var(--muted); }
.compare dd { margin: 0; font-weight: 700; }
.contact-list { list-style: none; padding: 0; margin: 0; display: grid; gap: .5rem; }
.contact-list a { display: inline-flex; gap: .5rem; align-items: center; }
.contact-list img { display: inline-block; }
.visually-hidden {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip: rect(0 0 0 0); white-space: nowrap;
}


.src { border: 1px solid var(--line); border-radius: 6px; background: var(--code-bg); }
.src > summary { padding: .5rem .8rem; color: var(--fg); font-size: .9rem; }
.src pre {
  margin: 0; padding: 0 .8rem .8rem; font-family: var(--font-mono);
  font-size: .78rem; line-height: 1.5; white-space: pre-wrap; overflow-wrap: anywhere;
}
