  display: inline-flex; gap: .4rem; align-items: center; cursor: pointer;
  padding: .35rem .8rem; border: 1px solid var(--line); border-radius: 6px; background: var(--surface);
}
.judge input { width: 1.05rem; height: 1.05rem; accent-color: var(--accent); margin: 0; }
.judge label:has(input:checked) { border-color: var(--accent); background: var(--accent-soft); }
