/* Layout: één leeskolom; elke casus = kop-regel, gestippeld testgebied, ingeklapte bevinding */
:root {
  --bg: #f4f6f8;
  --surface: #ffffff;
  --paper: #fbfcfd;
  --fg: #17202a;
  --muted: #55626f;
  --line: #c9d1d9;
  --accent: #1e5a85;
  --accent-soft: #e3edf5;
  --fail: #b42318;
  --fail-soft: #fdecea;
  --pass: #1a7a4a;
  --pass-soft: #e5f4ec;
  --code-bg: #eef1f4;
  --spec-red: #c0261b;
  --font-body: "Atkinson Hyperlegible", "Segoe UI", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, Consolas, monospace;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #11161c; --surface: #19212a; --paper: #1d262f;
    --fg: #e6ebf0; --muted: #9aa7b4; --line: #34414e;
    --accent: #7db6e3; --accent-soft: #1d3346;
    --fail: #ff8a7f; --fail-soft: #3a1d1b;
    --pass: #6fd3a0; --pass-soft: #163327;
    --code-bg: #0f1419; --spec-red: #ff7b70;
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --bg: #11161c; --surface: #19212a; --paper: #1d262f;
  --fg: #e6ebf0; --muted: #9aa7b4; --line: #34414e;
  --accent: #7db6e3; --accent-soft: #1d3346;
  --fail: #ff8a7f; --fail-soft: #3a1d1b;
  --pass: #6fd3a0; --pass-soft: #163327;
  --code-bg: #0f1419; --spec-red: #ff7b70;
  color-scheme: dark;
}
body {
  background: var(--bg); color: var(--fg);
  font-family: var(--font-body); font-size: 1rem; line-height: 1.55;
}
.wrap {
  max-width: 52rem; margin: 0 auto;
  padding-left: max(16px, env(safe-area-inset-left, 0px));
  padding-right: max(16px, env(safe-area-inset-right, 0px));
  padding-block: 2rem 4rem;
  display: grid; gap: 2.5rem;
}
a { color: var(--accent); }
:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }

/* Kop van de pagina */
.intro { display: grid; gap: .9rem; }
.eyebrow {
  font-family: var(--font-mono); font-size: .78rem; letter-spacing: .08em;
  text-transform: uppercase; color: var(--accent); margin: 0;
}
h1 { font-size: clamp(1.8rem, 5vw, 2.5rem); line-height: 1.15; margin: 0; text-wrap: balance; }
.intro p { margin: 0; max-width: 65ch; }
.howto { margin: 0; padding-left: 1.2rem; display: grid; gap: .3rem; color: var(--muted); }
.toolbar {
  display: flex; flex-wrap: wrap; gap: .75rem; align-items: center;
  padding: .75rem 1rem; background: var(--surface);
  border: 1px solid var(--line); border-radius: 8px;
}
.score { font-variant-numeric: tabular-nums; font-weight: 700; margin-right: auto; }
.btn {
  font: inherit; font-size: .9rem; cursor: pointer;
  padding: .4rem .85rem; border-radius: 6px;
  border: 1px solid var(--accent); background: var(--surface); color: var(--accent);
}
.btn:hover { background: var(--accent-soft); }
.cats { display: flex; flex-wrap: wrap; gap: .5rem; margin: 0; padding: 0; list-style: none; }
.cats a {
  display: inline-block; padding: .25rem .7rem; border-radius: 999px;
  background: var(--accent-soft); text-decoration: none; font-size: .9rem;
}

/* Categorieën en casussen */
.cat { display: grid; gap: 1.25rem; }
.cat > h2 {
  font-size: 1.5rem; margin: 0; padding-bottom: .4rem;
  border-bottom: 2px solid var(--fg); text-wrap: balance;
}
.cat-note { margin: -.5rem 0 0; color: var(--muted); max-width: 65ch; }
.case {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: 8px; padding: 1rem; display: grid; gap: .8rem; min-width: 0;
}
.case-head { display: flex; flex-wrap: wrap; gap: .5rem .9rem; align-items: baseline; }
.case-id {
  font-family: var(--font-mono); font-weight: 600; font-size: .85rem;
  color: var(--accent);
}
.case-title { margin: 0; font-weight: 700; margin-right: auto; }
.done { font-size: .9rem; display: inline-flex; gap: .35rem; align-items: center; color: var(--muted); }
.done input { width: 1.1rem; height: 1.1rem; accent-color: var(--accent); }
.case.is-done { opacity: .78; }

.spec-label {
  font-family: var(--font-mono); font-size: .72rem; letter-spacing: .08em;
  text-transform: uppercase; color: var(--muted); margin: 0 0 -.5rem;
}
.specimen {
  background: var(--paper); border: 2px dashed var(--line); border-radius: 6px;
  padding: 1rem; overflow-x: auto; min-width: 0;
}
.specimen > :first-child { margin-top: 0; }
.specimen > :last-child { margin-bottom: 0; }
.specimen h2 { font-size: 1.35rem; margin: .2rem 0 .4rem; }
.specimen h3 { font-size: 1.15rem; margin: .2rem 0 .4rem; }
.specimen h4 { font-size: 1rem; margin: .2rem 0 .4rem; }
.specimen p { margin: .3rem 0 .6rem; }
.specimen table { border-collapse: collapse; margin: .2rem 0; }
.specimen th, .specimen td {
  border: 1px solid var(--line); padding: .35rem .7rem; text-align: left;
  vertical-align: top;
}
.specimen th { background: var(--accent-soft); }
.specimen input[type="text"], .specimen input[type="email"] {
  font: inherit; padding: .35rem .5rem; border: 1px solid var(--muted);
  border-radius: 4px; background: var(--surface); color: var(--fg);
  max-width: 100%;
}
.specimen pre { font-family: var(--font-mono); font-size: .9rem; margin: 0; }
/* opmaakklassen die de fouten zichtbaar maken */
.fake-h { font-size: 1.35rem; font-weight: 700; margin: .2rem 0 .4rem; }
.fake-h-sm { font-size: 1.1rem; font-weight: 700; margin: .6rem 0 .3rem; }
.paginatitel { font-size: 1.6rem !important; }
.th-look { font-weight: 700; background: var(--accent-soft); }
.layout td, .layout th { border: 0 !important; background: none !important; padding: .2rem 1rem .2rem 0 !important; }
.layout th { font-weight: 400; color: var(--muted); white-space: nowrap; }
.grid-table { display: grid; grid-template-columns: max-content max-content; border: 1px solid var(--line); width: max-content; }
.grid-table > div { padding: .35rem .7rem; border-bottom: 1px solid var(--line); }
.grid-table .gh { font-weight: 700; background: var(--accent-soft); }
.kv { display: flex; gap: 2rem; }
.kv > div { display: grid; gap: .3rem; }
.kv-label { color: var(--muted); }
.radio-row { display: flex; gap: .4rem; align-items: center; margin: .2rem 0; }
.plain-list { list-style: none; padding: 0; margin: 0; display: grid; gap: .3rem; }
.plain-list li::before { content: "→ "; color: var(--accent); }

